        details: "Three resources in one, plus verified metro target lists. First, the Playbook: how care providers actually get clients \u2014 who refers (hospital discharge planners, skilled-nursing facilities, hospices, the aging network, senior communities, Medicaid case management agencies, elder-law attorneys, funeral homes, and care managers), the pathways into their referral pipelines (discharge lists, HCPF enrollment and EVV compliance, and preferred-provider relationships), what each source wants, how to approach them, and the legal line \u2014 so you build referrals without violating the federal Anti-Kickback Statute or Colorado law. Second, the verified Colorado Referral Directory: real, current phone numbers and websites for the resources that matter \u2014 CDPHE licensing, HCPF Medicaid provider services, Sandata EVV support, the CDLE Division of Labor Standards, the Secretary of State and DORA, the metro Area Agencies on Aging (DRCOG, Pikes Peak, and Larimer County), the county Adult Protective Services and 24-hour law-enforcement reporting pathway, and national gateways. Third, verified named-partner target lists for metro Denver, Colorado Springs, Aurora, and Fort Collins \u2014 real hospitals, skilled-nursing and rehab facilities, hospices, assisted-living communities, funeral homes, elder-law attorneys, and care managers, each with name, address, and phone. Fourth, the Worksheets & Tracker: a ready-to-use weekly system \u2014 a target list, an outreach tracker, relationship notes, and a referral results log. General business guidance, not legal advice; follow all applicable anti-kickback and referral laws, and verify every contact before you rely on it.",
