        details: "Three resources in one, plus verified metro target lists. First, the Playbook: how care providers actually get clients \u2014 who refers (hospital discharge planners, skilled-nursing facilities, hospices, the aging network, senior communities, payers, elder-law attorneys, funeral homes, and care managers), the official pathways into their referral pipelines (discharge lists, GAMMIS enrollment and CCSP/SOURCE credentialing, managed-care contracting, and preferred-provider agreements), what each source wants, how to approach them, scripts, and the legal line \u2014 so you build referrals without violating the federal Anti-Kickback Statute or Georgia's illegal-remuneration and patient-brokering laws. Second, the verified Georgia Referral Directory: real, current phone numbers and websites for the resources that matter \u2014 the Georgia ADRC and national gateways, DCH and Medicaid, Netsmart EVV support, Adult Protective Services and the Long-Term Care Ombudsman, the Secretary of State, the metro Area Agencies on Aging (Atlanta's Empowerline, Coastal, CSRA, and River Valley), and the state home-care and senior-living associations. Third, verified named-partner target lists for metro Atlanta, Savannah, Augusta, and Columbus \u2014 real hospitals, skilled-nursing and rehab facilities, hospices, assisted-living communities, funeral homes, elder-law attorneys, and care managers, each with name, address, and phone. Fourth, the Worksheets & Tracker: a ready-to-use weekly system \u2014 a master source list, your Target 25, an outreach planner, contact and referral logs, a source scorecard, outreach templates, and a one-page leave-behind builder. General business guidance, not legal advice; follow all applicable anti-kickback and referral laws, and verify every contact before you rely on it.",
