        details: "A rich, plain-language playbook for opening a brain-injury Adult Residential Facility in California, written for real people \u2014 not lawyers or consultants. It covers the one licensing path: get the home licensed by the California Department of Social Services as an ARF under Title 22 and the Community Care Facilities Act. Inside: the big picture and a step-by-step path; who regulates you (CDSS for licensing; regional centers and Medi-Cal managed-care plans for funding); business and insurance setup, plus the California zoning advantage (under Health & Safety Code \u00a7 1566.3, a six-or-fewer facility is a residential use by right \u2014 no conditional use permit); the CDSS process (orientation, Live Scan clearance, the 35-hour administrator certification, fire clearance, overconcentration, the application and inspection); the staff, training, and care team, with the medication reality stated plainly (assistance with self-administration, not administration); and an honest funding section \u2014 no single Medicaid per-diem, but a blend of SSI/SSP Non-Medical Out-of-Home Care, Regional Center placements (for developmental-disability-eligible residents), CalAIM Community Supports (for nursing-facility diversion/transition), county augmentations, and private pay. Plus common mistakes that delay a license, your first 90 days operating, two fully-worked metro examples (Los Angeles and the San Francisco Bay Area) with real local phone numbers and questions to ask, a key-terms glossary, and a core rules & references section. General information, not legal, tax, or billing advice; verify current details with the State of California.",
