        summary: "A referral and placement system built specifically for a California brain injury Adult Residential Facility \u2014 how an ARF fills its beds through California's brain injury service system, a verified directory of California referral sources, named-partner target lists for the state's largest metros, and the worksheets to run it week to week. Ready to customize to your home.",
        details: "California's brain injury pathway is a network, not a single waiver. Members arrive mainly from hospital and neuro-rehabilitation discharge and through the California Traumatic Brain Injury (TBI) Program \u2014 the Department of Rehabilitation's statewide network of nonprofit program sites providing community reintegration, supported living, and information and referral. Funding for residential care comes from Medi-Cal pathways (the HCBA Waiver, the Assisted Living Waiver's TBI tier, and managed-care plans), from regional centers for some, and from SSI/SSP and private pay. This system is built for that pathway. Part One is an eleven-part playbook \u2014 the source map, the placement pipeline and the anti-kickback legal line, what each source wants, outreach scripts, becoming a preferred provider, online presence, a weekly rhythm, and metrics \u2014 plus a referral-story guide and a first-90-days action plan. Part Two is a verified California directory: statewide sources (the TBI Program, Medi-Cal HCBS waivers, regional centers, the Brain Injury Association of California, and CDSS) and named-partner target lists for Los Angeles, San Diego, the San Francisco Bay Area, and Sacramento \u2014 including Rancho Los Amigos, Santa Clara Valley Medical Center, and Centre for Neuro Skills. Part Three is a toolkit of worksheets. A professionally structured, editable resource, ready to customize. General educational information, not legal advice; verify contacts and the anti-kickback rules before relying on them.",
