        details: "Written to California's Home Care Organization license \u2014 the Home Care Services Consumer Protection Act (Health and Safety Code Sections 1796.10\u20131796.63, from AB 1217) and Title 22, Division 6, Chapter 8 \u2014 licensed by the California Department of Social Services (CDSS), Home Care Services Bureau. An HCO is a non-medical provider: Home Care Aides assist with activities of daily living, companion and homemaker services, and self-administered medication (they do not provide skilled nursing or administer medications), and this manual is written honestly to that scope. Fifty-four policies across six sections \u2014 Administration & Licensing, Home Care Aide Management (HR), Client Services & Care Planning, Health/Safety & Emergency, Compliance/EVV & Privacy, and Program Quality & Outcomes \u2014 each following a consistent Purpose / Definitions / Policy / Procedure / Related Forms structure with genuine home-care-specific reasoning, bracketed fields, and a Document History table. Built to the real rules: Home Care Aide registration and the Registry (\u00a7 1796.12), background examination via Live Scan to the DOJ and FBI (\u00a7 1796.23), tuberculosis clearance (\u00a7 1796.45), the five-hour entry and five-hour annual training, the operating requirements including the $10,000 employee dishonesty bond (\u00a7 1796.55), California labor law (the Domestic Worker Bill of Rights, daily overtime, breaks, SB 525 and SB 1350), Electronic Visit Verification (CalEVV), and HIPAA \u2014 with abuse reporting the California way. The manual is structured to align with recognized home-care accreditation frameworks (CHAP and ACHC) \u2014 aligned to, not reproducing, their proprietary standards \u2014 which payers and referral sources often prefer. You add your organization's details and adapt the procedures to how you actually operate. General information, not legal advice; verify current details with CDSS.",
