        details: "A plain-language, step-by-step playbook for opening a Virginia Home Care Organization, written for real people \u2014 not lawyers or consultants. It explains the license and the scope line that decides whether you even need it (hands-on personal care requires the license; companion-only is exempt), Virginia's open-entry framework with no Certificate of Public Need, and the whole path: forming your business, securing the registered nurse who must supervise personal care and build each plan of services, applying through the OLC Portal at least sixty days before opening with the triennial fee and three-month reserve operating funds, and passing the OLC survey. It covers hiring and screening (the Virginia State Police criminal record report, the sworn disclosure, and the barrier-crimes bar), getting paid (DMAS enrollment, Cardinal Care and the CCC Plus waiver, agency-directed versus consumer-directed services, and the Provider Choice EVV model), a home and fire-safety checklist that answers the sprinkler question, and a who-to-call-and-what-to-ask section with verified statewide contacts. Two fully worked examples \u2014 Northern Virginia and Richmond \u2014 show it coming together with real, verified local referral partners. General information, not legal, tax, or accreditation advice; verify current details with the Commonwealth of Virginia.",
